"use client";
import React, { useState, useEffect } from "react";
import Image from "next/image";
import Icon1 from "./icons/icon1.svg";
import Icon2 from "./icons/icon2.svg";
import Icon3 from "./icons/icon3.svg";
import Icon4 from "./icons/icon4.svg";
import Icon5 from "./icons/icon5.svg";
import Icon6 from "./icons/icon6.svg";
import Icon7 from "./icons/icon7.svg";
import Icon8 from "./icons/icon8.svg";
import Icon9 from "./icons/icon9.svg";
import Icon10 from "./icons/icon10.svg";
import Icon11 from "./icons/icon11.svg";
import Icon12 from "./icons/icon12.svg";
import Icon13 from "./icons/icon13.svg";
import Icon14 from "./icons/icon14.svg";
import Icon15 from "./icons/icon15.svg";
import Icon16 from "./icons/icon16.svg";
import CategoriesDetails from "./CategoriesDetails";

const icons = [
  Icon1, Icon2, Icon3, Icon4, Icon5, Icon6, Icon7, Icon8,
  Icon9, Icon10, Icon11, Icon12, Icon13, Icon14, Icon15, Icon16,
];

const HelpHero = () => (
  <section className="tw-relative tw-overflow-hidden">
    <div
      className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-top"
      style={{
        backgroundImage:
          "url('https://travelshopbooking.com/images/bgHelpCenter.jpg')",
      }}
      aria-hidden="true"
    />
    <div
      className="tw-absolute tw-inset-0"
      style={{
        background:
          "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.6) 100%)",
      }}
      aria-hidden="true"
    />
    <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-16 md:tw-py-24 tw-text-center">
      <h1 className="tw-text-[clamp(30px,4.5vw,52px)] tw-font-bold tw-tracking-tight tw-text-white tw-m-0">
        How can we help you?
      </h1>
    </div>
  </section>
);

const Categories = () => {
  const [categories, setCategories] = useState([]);
  const [questions, setQuestions] = useState([]);
  const [selectedQuestion, setSelectedQuestion] = useState(null);
  const [selectedQuestionId, setSelectedQuestionId] = useState(null);
  const [selectedCategoryId, setSelectedCategoryId] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [showQuestionsList, setShowQuestionsList] = useState(false);
  const [showQuestionDetails, setShowQuestionDetails] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch(
          `/api/apiv2/b2c/help/categories?help_category=question.customer`
        );
        if (!response.ok) throw new Error("Network response was not ok");
        const jsonData = await response.json();
        setCategories(jsonData.categories);
      } catch (error: any) {
        setError(error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    const fetchQuestions = async () => {
      if (selectedCategoryId) {
        try {
          const response = await fetch(
            `/api/apiv2/b2c/help/questions?category_id=${selectedCategoryId}`
          );
          if (!response.ok) throw new Error("Network response was not ok");
          const jsonData = await response.json();
          setQuestions(jsonData.questions);
        } catch (error: any) {
          setError(error);
        }
      }
    };
    fetchQuestions();
  }, [selectedCategoryId]);

  const handleCategoryClick = (categoryId: any, category: any) => {
    setSelectedCategoryId(categoryId);
    setSelectedCategory(category);
    setSelectedQuestion(null);
    setShowQuestionsList(true);
    setShowQuestionDetails(false);
  };

  const handleQuestionClick = async (questionId: any) => {
    setSelectedQuestionId(questionId);
    try {
      const response = await fetch(
        `/api/apiv2/b2c/help/questiondetail?id=${questionId}`
      );
      if (!response.ok) throw new Error("Network response was not ok");
      const questionDetail = await response.json();
      setSelectedQuestion(questionDetail);
      setShowQuestionDetails(true);
    } catch (error: any) {
      setError(error);
    }
  };

  if (loading)
    return (
      <div className="tw-font-display tw-py-24 tw-text-center tw-text-[#5d556c]">
        Loading...
      </div>
    );
  if (error)
    return (
      <div className="tw-font-display tw-py-24 tw-text-center tw-text-[#dc2626]">
        Error loading help center.
      </div>
    );

  if (showQuestionsList) {
    return (
      <CategoriesDetails
        categories={categories}
        selectedCategory={selectedCategory}
        handleCategoryClick={handleCategoryClick}
        handleQuestionClick={handleQuestionClick}
        showQuestionsList={showQuestionsList}
        questions={questions}
        selectedQuestion={selectedQuestion}
        selectedQuestionId={selectedQuestionId}
        showQuestionDetails={showQuestionDetails}
      />
    );
  }

  return (
    <main className="tw-font-display tw-bg-white">
      <HelpHero />
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {categories
              .filter((category: any) => category.id !== "covid-19-support-hygiene")
              .map((category: any, index) => (
                <button
                  key={category.id}
                  type="button"
                  onClick={() => handleCategoryClick(category.id, category)}
                  className="tw-flex tw-items-start tw-gap-4 tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 tw-text-left tw-cursor-pointer hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
                >
                  <div className="tw-flex tw-h-12 tw-w-12 tw-shrink-0 tw-items-center tw-justify-center tw-rounded-xl tw-bg-[#854ec9]/10">
                    <Image src={icons[index + 1]} alt="" width={24} height={24} />
                  </div>
                  <div className="tw-min-w-0">
                    <h2 className="tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-m-0">
                      {category.name}
                    </h2>
                    <p
                      className="tw-mt-1.5 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]"
                      dangerouslySetInnerHTML={{ __html: category.description }}
                    />
                  </div>
                </button>
              ))}
          </div>
        </div>
      </section>
    </main>
  );
};

export default Categories;
