"use client";
import React from "react";
import Image from "next/image";
import Icon1 from "./icons/icon1.svg";
import Icon2 from "./icons/icon2.svg";
import Icon3 from "./icons/icon3.svg";
import Icon4 from "./icons/icon4.svg";
import Icon5 from "./icons/icon5.svg";
import Icon6 from "./icons/icon6.svg";
import Icon7 from "./icons/icon7.svg";
import Icon8 from "./icons/icon8.svg";
import Icon9 from "./icons/icon9.svg";
import Icon10 from "./icons/icon10.svg";
import Icon11 from "./icons/icon11.svg";
import Icon12 from "./icons/icon12.svg";
import Icon13 from "./icons/icon13.svg";
import Icon14 from "./icons/icon14.svg";
import Icon15 from "./icons/icon15.svg";
import Icon16 from "./icons/icon16.svg";

const icons = [
  Icon1, Icon2, Icon3, Icon4, Icon5, Icon6, Icon7, Icon8,
  Icon9, Icon10, Icon11, Icon12, Icon13, Icon14, Icon15, Icon16,
];

const CategoriesDetails = ({
  categories,
  selectedCategory,
  handleCategoryClick,
  handleQuestionClick,
  showQuestionsList,
  questions,
  selectedQuestion,
  selectedQuestionId,
  showQuestionDetails,
}: any) => {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-top"
          style={{
            backgroundImage:
              "url('https://travelshopbooking.com/images/bgHelpCenter.jpg')",
          }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.6) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-14 md:tw-py-20 tw-text-center">
          <h1 className="tw-text-[clamp(28px,4vw,46px)] tw-font-bold tw-tracking-tight tw-text-white tw-m-0">
            How can we help you?
          </h1>
        </div>
      </section>

      <section className="tw-py-10 md:tw-py-14">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[280px_minmax(0,340px)_1fr] tw-gap-5 lg:tw-gap-6">
            {/* Category sidebar */}
            <aside className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-3 lg:tw-self-start">
              <ul className="tw-m-0 tw-p-0 tw-list-none tw-space-y-1">
                {categories
                  .filter(
                    (category: any) => category.id !== "covid-19-support-hygiene"
                  )
                  .map((category: any, index: any) => {
                    const isActive = selectedCategory?.id === category.id;
                    return (
                      <li key={category.id}>
                        <button
                          type="button"
                          onClick={() =>
                            handleCategoryClick(category.id, category)
                          }
                          className={`tw-flex tw-w-full tw-items-center tw-gap-3 tw-rounded-xl tw-px-3 tw-py-2.5 tw-text-left tw-text-[14px] tw-font-semibold tw-cursor-pointer tw-transition-colors ${
                            isActive
                              ? "tw-bg-[#f4f0ff] tw-text-[#854ec9]"
                              : "tw-text-[#14101c] hover:tw-bg-[#faf9fc]"
                          }`}
                        >
                          <Image
                            src={icons[index + 1]}
                            alt=""
                            width={20}
                            height={20}
                            className="tw-shrink-0"
                          />
                          {category.name}
                        </button>
                      </li>
                    );
                  })}
              </ul>
            </aside>

            {/* Questions list */}
            <div className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 lg:tw-self-start">
              {selectedCategory && (
                <div>
                  <h2 className="tw-text-[20px] tw-font-bold tw-text-[#14101c] tw-m-0">
                    {selectedCategory.name}
                  </h2>
                  <p
                    className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]"
                    dangerouslySetInnerHTML={{
                      __html: selectedCategory.description,
                    }}
                  />
                </div>
              )}

              {showQuestionsList && questions && questions.length > 0 && (
                <ul className="tw-mt-5 tw-pt-5 tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0] tw-m-0 tw-p-0 tw-list-none tw-space-y-1">
                  {questions.map((question: any) => {
                    const isActive = selectedQuestionId === question.id;
                    return (
                      <li key={question.id}>
                        <button
                          type="button"
                          onClick={() => handleQuestionClick(question.id)}
                          className={`tw-w-full tw-rounded-xl tw-px-3 tw-py-2.5 tw-text-left tw-text-[14px] tw-cursor-pointer tw-transition-colors ${
                            isActive
                              ? "tw-bg-[#f4f0ff] tw-font-semibold tw-text-[#854ec9]"
                              : "tw-text-[#5d556c] hover:tw-bg-[#faf9fc] hover:tw-text-[#14101c]"
                          }`}
                        >
                          {question.message}
                        </button>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>

            {/* Answer */}
            <div className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 tw-min-h-[200px]">
              {selectedQuestion && showQuestionDetails ? (
                <div
                  className="tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c] [&_img]:tw-max-w-full [&_a]:tw-text-[#854ec9] [&_a]:tw-font-semibold"
                  dangerouslySetInnerHTML={{ __html: selectedQuestion.answer }}
                />
              ) : (
                <p className="tw-m-0 tw-text-[14px] tw-text-[#6b6577]">
                  Select a question to see the answer.
                </p>
              )}
            </div>
          </div>
        </div>
      </section>
    </main>
  );
};

export default CategoriesDetails;
